// Focused correctness rules for application, Worker, scripts, and tests.
// Formatting is intentionally independent from this quality gate.
import reactHooks from 'eslint-plugin-react-hooks'
import tseslint from 'typescript-eslint'

export default [
  // src/router.ts is generated by generouted and carries a blanket
  // `/* eslint-disable */`. Linting it produces only an "unused disable
  // directive" warning on every run, so ignore it — the linter should stay
  // silent unless there's a real Rules of Hooks violation.
  // `**/._*` covers macOS AppleDouble metadata files, which are binary and
  // otherwise hard-fail the lint with "Parsing error: Invalid character".
  // `.deepspace/**` holds Playwright artifacts (test-results, playwright-report)
  // that the test runner rotates while a lint may be scanning them.
  { ignores: ['dist/**', 'node_modules/**', '.wrangler/**', '.vite/**', '.deepspace/**', 'src/router.ts', '**/._*'] },
  {
    files: ['**/*.{ts,tsx}'],
    languageOptions: {
      parser: tseslint.parser,
      parserOptions: { ecmaFeatures: { jsx: true } },
    },
    plugins: { 'react-hooks': reactHooks },
    rules: {
      'react-hooks/rules-of-hooks': 'error',
      'constructor-super': 'error',
      'no-dupe-args': 'error',
      'no-dupe-else-if': 'error',
      'no-dupe-keys': 'error',
      'no-unreachable': 'error',
      'no-unsafe-finally': 'error',
      'valid-typeof': 'error',
    },
  },
]
